class KnowledgeModule(PromptModule):
    """知识点模块：构建知识点信息和引用列表"""

    MAX_DESCRIPTION_LENGTH = 400

    def __init__(
        self,
        nodes: List[KnowledgeNode],
        details_fetcher: Optional[Callable[[List[str]], Dict[str, Dict]]] = None
    ):
        """
        初始化知识点模块

        Args:
            nodes: 知识点节点列表
            details_fetcher: 获取知识点详情的函数（可选）
                            函数签名: (ids: List[str]) -> Dict[str, Dict]
                            返回格式: {"kp_001": {"text": "描述内容", ...}, ...}
        """
        self.nodes = nodes or []
        # 优先使用传入的 fetcher，否则使用全局默认的
        self.details_fetcher = details_fetcher or get_default_details_fetcher()

    @property
    def is_empty(self) -> bool:
        """判断是否没有知识点"""
        return len(self.nodes) == 0

    def build(self) -> str:
        """构建知识点模块内容"""
        if self.is_empty:
            return ""

        sections = [
            "## 知识点信息",
            "",
            self._build_knowledge_details(),
            "",
            self._build_knowledge_reference()
        ]

        return "\n".join(sections)

    def _fetch_details(self, ids: List[str]) -> Dict[str, Dict]:
        """
        获取知识点详情

        Args:
            ids: 知识点 ID 列表

        Returns:
            知识点详情字典，格式: {id: {"text": "...", ...}}
        """
        if not self.details_fetcher or not ids:
            return {}

        try:
            result = self.details_fetcher(ids)

            # 确保返回值是字典格式
            if result is None:
                return {}

            # 如果返回的是列表，转换为字典
            if isinstance(result, list):
                return {
                    item.get("id"): item 
                    for item in result 
                    if isinstance(item, dict) and item.get("id")
                }

            # 如果已经是字典，直接返回
            if isinstance(result, dict):
                return result

            logger.warning(f"get_details_list 返回了意外的类型: {type(result)}")
            return {}

        except Exception as e:
            logger.warning(f"获取知识点详情失败: {e}")
            return {}

    def _build_knowledge_details(self) -> str:
        """构建知识点详情"""
        # 收集所有知识点 ID
        all_ids = []
        for node in self.nodes:
            if node.id:
                all_ids.append(node.id)
            for child in node.children:
                if child.id:
                    all_ids.append(child.id)

        # 批量获取详情
        details_map = self._fetch_details(all_ids)

        # 构建输出
        lines = []
        for node in self.nodes:
            details = details_map.get(node.id, {}) or {}
            description = (details.get("text", "") or node.description)[:self.MAX_DESCRIPTION_LENGTH]

            lines.append(f"### {node.name}")
            lines.append(f"- **ID**: `{node.id}`")
            lines.append(f"- **名称**: {node.name}")
            if node.type:
                lines.append(f"- **类型**: {node.type}")
            if description:
                lines.append(f"- **描述**: {description}")

            # 子知识点
            if node.children:
                lines.append("- **子知识点**:")
                for child in node.children:
                    child_details = details_map.get(child.id, {}) or {}
                    child_desc = (child_details.get("text", "") or child.description)[:self.MAX_DESCRIPTION_LENGTH]

                    lines.append(f"  - **ID**: `{child.id}`, **名称**: {child.name}")
                    if child_desc:
                        lines.append(f"    描述: {child_desc}")

            lines.append("")

        return "\n".join(lines)

